import{_ as e,o,c as s,a2 as a}from"./chunks/framework.D66Xq0Kv.js";const w=JSON.parse('{"title":"Add New Institution","description":"","frontmatter":{"title":"Add New Institution"},"headers":[],"relativePath":"docs/tools/add-new-institution.md","filePath":"docs/tools/add-new-institution.md","lastUpdated":1793412416000}'),n={name:"docs/tools/add-new-institution.md"};function r(i,t,d,l,h,u){return o(),s("div",null,[...t[0]||(t[0]=[a('<h1 id="add-new-institution" tabindex="-1">Add New Institution <a class="header-anchor" href="#add-new-institution" aria-label="Permalink to &quot;Add New Institution&quot;">​</a></h1><p>OrbySystems reads statements with <strong>parsers</strong>, one per institution and format. Add New Institution is for when yours isn&#39;t read yet — or when an existing parser reads a statement wrongly. Either way, a parser can be added or updated without anyone seeing your money.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><ol><li><strong>Pick a statement.</strong> OrbySystems first tries the parsers it already has, so you can tell whether one reads it wrongly. If one does, describe what&#39;s wrong.</li><li><strong>Make a scrambled copy.</strong> The copy keeps the statement&#39;s layout, but names, merchants, account numbers and amounts are replaced with invented ones, and dates keep only their month and day.</li><li><strong>Review it.</strong> Read the scrambled copy beside the original, along with a report of what was replaced and anything of the original still in it. Confirm that nothing of yours remains before going on.</li><li><strong>Send it to OrbySystems.</strong> OrbySystems builds the parser from the scrambled copy alone and sends it back, signed.</li></ol><p>OrbySystems tries the result on your real statement and installs it only if it reads it correctly. Nothing leaves your computer until you choose to send it.</p><h2 id="following-a-request" tabindex="-1">Following a request <a class="header-anchor" href="#following-a-request" aria-label="Permalink to &quot;Following a request&quot;">​</a></h2><p>A sample you send to OrbySystems opens a request. The <strong>Outstanding Requests</strong> button at the top of the tool shows it, and lights up when OrbySystems writes back. When the parser arrives, it is installed and tried on your statement from there. You can check the result with the <a href="/docs/tools/transactions-extractor">Transactions Extractor</a>.</p>',7)])])}const m=e(n,[["render",r]]);export{w as __pageData,m as default};
